import numpy as np

def ichol(A):
    """
    Inputs:
    A : Matrix, 2D array N * N

    Outputs:
    K : Matrix, 2D array N * N (incomplete Cholesky factorization)
    """
    N = len(A)
    K = np.zeros((N, N))

    for i in range(N):
        for k in range(i):
            if A[i,k] != 0 or A[k,i] != 0:
                K[i,k] = A[i,k]

        K[i,i] = np.sqrt(max(0, A[i,i] - np.sum(K[i,:i]**2)))

        for j in range(i+1, N):
            if A[j,i] != 0 or A[i,j] != 0:
                K[j,i] = (A[j,i] - np.sum(K[j,:i]*K[i,:i])) / K[i,i]

    return K

