from scipy.linalg import tensor

def tensor_product(*args):
    return tensor(args)

def pauli_y(n):
    return tensor([[[0, -1j], [1j, 0]]] * n)

def n_tangle(psi):
    """Returns the n-tangle of pure state psi"""
    n = int(np.log2(len(psi)))
    assert n % 2 == 0, "n must be even"
    sigma_y = pauli_y(n)
    psi_conj = np.conjugate(psi)
    return np.abs(np.dot(psi, tensor_product(sigma_y, psi_conj)))**2

import numpy as np

def orthogonalize(A):
    n = A.shape[0]
    Q = np.zeros_like(A)
    for i in range(n):
        v = A[i, :]
        for j in range(i):
            Q[j, :] -= np.dot(v, Q[j, :]) / np.linalg.norm(Q[j, :])**2 * Q[j, :]
        Q[i, :] = (v - np.sum(Q[:i, :], axis=0)) / np.linalg.norm(v - np.sum(Q[:i, :], axis=0))
    return Q

import numpy as np

def reciprocal(*args):
    if len(args) == 1:
        a = args[0]
        rec = np.array([2 * np.pi / a])
    elif len(args) == 2:
        a, b = args
        cross_product = np.cross(a, b)
        dot_product = np.dot(a, np.cross(b))
        rec = [np.array([2 * np.pi * cross_product / dot_product]), np.array([-2 * np.pi * cross_product / dot_product])]
    elif len(args) == 3:
        a, b, c = args
        rec = np.linalg.inv(np.dot(a.T, b)) @ np.dot(b.T, c)
    else:
        raise ValueError("Invalid number of input vectors. Expected between 1 and 3.")
    return [np.array([rec]) if isinstance(rec, list) else rec]

