    return U

import numpy as np

def U_i(r_i, sigma, epsilon):
    return 4 * epsilon * ((sigma/r_i)**12 - (sigma/r_i)**6)

def U_system(positions, sigma, epsilon):
    N = len(positions)
    U = 0
    for i in range(N):
        for j in range(i+1, N):
            r_ij = np.linalg.norm(positions[i] - positions[j])
            U += U_i(r_ij, sigma, epsilon)
    return U

def MC(sigma, epsilon, T, init_positions, MC_steps, dispSize):
    beta = 1 / T
    E_trace = []
    positions = init_positions.copy()
    for _ in range(MC_steps):
        i = np.random.randint(0, len(positions))
        new_position = positions[i] + np.random.normal(0, dispSize, 3)
        U_new = U_system(np.append(positions[:i], new_position, axis=0), sigma, epsilon)
        U_old = U_system(positions, sigma, epsilon)
        acc_prob = min(1, np.exp(-beta * (U_new - U_old)))
        if np.random.rand() < acc_prob:
            positions[i] = new_position
        E_trace.append(U_old)
    return np.array(E_trace)

