import numpy as np

# Helper functions
def compute_real_part(z):
    return z.real

def compute_imag_part(z):
    return z.imag

def calculate_h1(H):
    return compute_real_part(H[0, 1])

def calculate_h2(H):
    return -compute_imag_part(H[0, 1])

def calculate_h3(H):
    return (H[0, 0] - H[1, 1]) / 2

def calculate_h4(H):
    return compute_real_part(H[0, 2])

def calculate_h5(H):
    return -compute_imag_part(H[0, 2])

def calculate_h6(H):
    return compute_real_part(H[1, 2])

def calculate_h7(H):
    return -compute_imag_part(H[1, 2])

def calculate_h8(H):
    return (np.sqrt(3) / 6) * (H[0, 0] + H[1, 1] - 2 * H[2, 2])

